-- Seeds the plan_templates catalog (Phase 3 of the default-plan-templates
-- epic, see TODOS.md) with real, sourced, well-known reading plans.
--
-- Content was researched and transcribed (citations only -- no devotional
-- commentary/prose was copied from any source) from each plan's real
-- published schedule, then structurally validated: every day_number forms
-- a clean 1..N sequence with no gaps/duplicates/empty entries, and total_days
-- matches the row count exactly.
--
--   * M'Cheyne Reading Plan (365 days) -- Robert Murray M'Cheyne's 1842
--     calendar, 4 daily readings. Source: mcheyne.info/David Haslam PDF
--     digitization of the original; cross-checked against The Gospel
--     Coalition's M'Cheyne archive for 3 sample dates.
--   * Chronological Bible in a Year (365 days) -- scripture in historical/
--     narrative order. Source: the Back to the Bible plan distributed via
--     ESV.org; cross-checked against Blue Letter Bible's chronological plan.
--   * Navigators Bible Reading Plan (300 days) -- formerly Discipleship
--     Journal's plan, 4 parallel daily tracks, 25 readings/month with
--     built-in catch-up days. Source: navigators.org's current plan PDF;
--     cross-checked against its YouVersion hosting for day 1.
--   * Two Year Chronological (730 days) -- OT weekdays / NT weekends.
--     Source: the plan's live YouVersion pages (bible.com/reading-plans/52280).
--   * A Chapter a Day: Bible in 3 Years (1095 days) -- Celebration Church's
--     plan, stitched from its 12 quarterly YouVersion sub-plans.
--     Source: bible.com/reading-plans (ids 3409, 3413-3415, 3600,
--     3637-3639, 3684, 3791, 3804-3805).
--   * Whole Bible in Under 2 Years (683 days) -- Life.Church's plan, OT
--     chronological + daily NT passage, weekly reflection day.
--     Source: bible.com/reading-plans/17108.
--   * The One Year Bible (365 days) -- Tyndale House's classic branded
--     plan, daily 4-way interleave of OT/NT/Psalms/Proverbs.
--     Source: bible.com/reading-plans/60.
--   * The Bible Recap (365 days) -- Tara-Leigh Cobble's chronological plan
--     tied to her podcast/book. Source: bible.com/reading-plans/17553.
--
-- All YouVersion-sourced plans were fetched programmatically (every day
-- page for the plan, scripture-reference links only) and validated for
-- gaps/duplicates/empty days before being written here.
--
-- Applied manually via the Supabase SQL Editor per this repo's workflow.

-- M'Cheyne Reading Plan (365 days)
WITH t AS (
  INSERT INTO plan_templates (name, description, category, total_days)
  VALUES ('M''Cheyne Reading Plan', 'Robert Murray M''Cheyne''s classic 1842 calendar -- four daily readings (two family, two secret) that take you through the Old Testament once and the New Testament and Psalms twice in a year.', 'Whole Bible', 365)
  RETURNING id
)
